APP("passage_gym", "Passage Gym", "Reading comprehension drills for SAT, ACT, GRE and IELTS", "Education", ["#5D4037", "#26A69A", "#FFA000"], "book",
 "Passage Gym turns any passage into exam-style questions for your test, teaches the reading strategy each question type needs, drills vocabulary in context and checks your reading speed against the test's real pace.",
 "You are a reading-skills coach for standardised tests: you show where the answer lives in the text, name the trap in every wrong option, and build speed without skimming into guesses.",
 "Read faster, miss less", "Your test sets the passage style, question types and pace.", ["Any passage into exam questions", "Strategy per question type", "Speed and pacing drills"],
 [NAME, CH("test", "Test", ["SAT", "ACT", "GRE", "IELTS", "TOEFL", "LSAT", "Other"]), TXT("goal", "Goal", "stop losing marks on inference questions")],
 [T("make", "Passage → questions", "Paste anything, get exam-style questions", "📄", [LONG("passage", "Paste a passage", "paste 200–600 words from an article, textbook or novel…"), CH("n", "Questions", ["4", "6", "8"], "6")],
    "Write {n} questions in the profile test's real style on this passage: {passage}. Cards (question with lettered options, meta = question type), a table (No. | Answer | Sentence that proves it | Trap in the best distractor), and a callout on the time this passage should take on the profile's test.", "cards, table, callout", "Make questions", "Reading closely…"),
  T("generate", "Fresh practice passage", "Original passage in your test's style", "🆕", [CH("genre", "Genre", ["Science", "Social science", "Humanities", "Literary fiction", "Historical document", "Paired passages"], "Science"), CH("length", "Length", ["Short (200 words)", "Medium (400 words)", "Long (700 words)"], "Medium (400 words)")],
    "Write an original {genre} passage of {length} in the style the profile's test uses as a text section, then 5 exam-format questions as cards (question with options, meta = type), a table (No. | Answer | Evidence location), and bullets of 4 vocabulary-in-context words from the passage with their meaning here.", "text, cards, table, bullets", "Generate", "Writing the passage…"),
  T("strategy", "Question-type strategy", "Method, kill rules, worked example", "🧭", [CH("qtype", "Question type", ["Main idea", "Inference", "Vocabulary in context", "Function / purpose", "Author's tone", "Evidence support", "Paired passages"], "Inference")],
    "Coach {qtype} questions for the profile's test: steps for the method (what to read first, what to underline, how to predict before looking at options), a table (Wrong-answer pattern | How it looks | Kill rule), a text worked example with a 120-word mini-passage and one question, and a quote with a one-line reminder to use in the exam.", "steps, table, text, quote", "Coach me", "Underlining…"),
  T("speed", "Reading speed check", "WPM vs what your test demands", "⏱️", [NUM("words", "Words in what you just read", "450"), NUM("seconds", "Seconds it took", "180"), CH("understood", "Understanding", ["Got it all", "Got the gist", "Lost the thread"], "Got the gist")],
    "Reading speed: {words} words in {seconds} seconds with understanding '{understood}'. Give kv (words per minute, target WPM for the profile's test, gap), a table (Test | Passage length | Questions | Minutes | Required WPM) comparing common tests, steps for a 2-week speed programme with daily drills, and a callout on when faster reading starts costing accuracy.", "kv, table, steps, callout", "Check speed", "Timing you…"),
  T("explain", "Explain a missed question", "Where the answer lived and why you missed it", "🔎", [LONG("q", "Question, extract, options and answers", "paste the passage extract, question, options, your answer and the correct answer…")],
    "Explain this missed question: {q}. Text on exactly where in the extract the answer is proven, a table (Option | Why right or wrong | Trap type), bullets on the reading habit that led to the miss, and a quote with the rule to apply next time.", "text, table, bullets, quote", "Explain", "Tracing evidence…")])

APP("exam_nerves", "Exam Nerves", "Calm, focused and rested on test day", "Education", ["#00897B", "#7E57C2", "#FFCA28"], "sun",
 "Exam Nerves builds a test-week routine for sleep, food and light revision, gives in-exam reset techniques for blanking and panic, rewrites the thoughts that spiral, and debriefs bad scores without the doom.",
 "You are a calm performance coach trained in CBT-style techniques for exam anxiety: practical, warm, never dismissive, and clear about when someone needs professional support.",
 "Perform like you practised", "Your test, date and what nerves do to you shape the plan.", ["Test-week sleep, food and taper", "60-second resets for the exam room", "Debriefs that turn a bad score into a plan"],
 [NAME, TXT("exam", "Exam", "IELTS on 14 June"), CH("symptom", "Nerves show up as", ["Blanking", "Racing heart", "Can't sleep", "Procrastination", "Perfectionism"], multi=True), CH("history", "Past exams", ["Usually fine", "Under-perform", "Have frozen before"])],
 [T("week", "Test-week plan", "Taper, sleep and the night before", "🗓️", [TXT("date", "Test date & time", "Saturday 8:30", True), CH("state", "Revision state", ["Ahead", "On track", "Behind", "Panicking"], "On track")],
    "Build the 7 days before {date} for someone who is {state}: table (Day | Revision: light, normal or none | Sleep window | Movement | Evening wind-down), a checklist for the night before and the morning (kit, route, breakfast, caffeine cut-off), bullets on the taper principle and why cramming the last night backfires, and a callout on the sleep and wake times to lock in from tonight.", "table, checklist, bullets, callout", "Plan the week", "Dimming the lights…"),
  T("reset", "In-exam reset", "60 seconds, silent, at your desk", "🫁", [CH("moment", "What is happening", ["Mind went blank", "Heart racing before it starts", "Stuck on one question", "Running out of time", "Everyone else looks finished"], "Mind went blank")],
    "For '{moment}' with the profile's symptoms: steps for a 60-second reset that can be done silently at the desk (breath count, muscle release, anchor phrase, next action), a quote with a 2-sentence self-instruction script, bullets on what makes the moment worse, and a callout on the rule for when to move on from a question.", "steps, quote, bullets, callout", "Reset me", "Breathing in…"),
  T("thoughts", "Rewrite the spiral", "Catch the thought, balance it", "🌀", [LONG("thought", "What your head is saying", "if I fail this everyone will know I'm a fraud…")],
    "Work with this thought: {thought}. A table (Thought | Distortion | Evidence for | Evidence against | Balanced version), a quote with the balanced thought as a one-line card to keep, steps for a 5-minute worry-postponement routine, and a callout on signs that this has moved beyond normal nerves.", "table, quote, steps, callout", "Rewrite it", "Untangling…"),
  T("debrief", "Debrief a bad score", "Separate prep, execution and luck", "📉", [LONG("what", "What happened", "got 6.0 in writing again, ran out of time on task 2…")],
    "Debrief this: {what}. Text that separates preparation, execution and luck honestly, a table (Factor | Controllable? | What to change), steps for the next 14 days, bullets of what went right and should be kept, and a quote with the one-sentence story to tell yourself about this attempt.", "text, table, steps, bullets, quote", "Debrief", "Looking calmly…"),
  T("fuel", "Sleep & fuel for test day", "Hour-by-hour from waking to the last question", "🥣", [TXT("start", "Exam start time & length", "9:00, 3 hours", True), CH("caffeine", "Caffeine habit", ["None", "1 cup", "2–3 cups", "Lots"], "1 cup")],
    "For an exam at {start} with caffeine habit '{caffeine}': a table (Time | Do | Eat or drink) from waking to the end of the exam, kv (bedtime, wake time, last caffeine, breakfast, snack to bring), bullets on foods that cause a mid-exam crash, and a callout on the risks of new supplements or energy drinks on the day.", "table, kv, bullets, callout", "Plan the day", "Setting the alarm…")], CALM)

APP("miss_log", "Miss Log", "Your wrong answers, analysed into a score plan", "Education", ["#D81B60", "#1E88E5", "#FFC107"], "graph",
 "Miss Log turns the questions you get wrong on any standardised test into an error taxonomy, a weakness heat-map, targeted re-drills and a score projection, so every practice test changes what you study next.",
 "You are a data-minded test-prep analyst: you categorise every miss by cause, show trends in tables, and prescribe the smallest fix with the biggest score effect.",
 "Every miss is a data point", "Your test and score history make the projections real.", ["Error taxonomy from any practice test", "Weakness heat-map by topic", "Score projections and next steps"],
 [NAME, CH("test", "Test", ["SAT", "ACT", "GRE", "GMAT", "IELTS", "Certification exam", "Other"]), TXT("history", "Practice scores so far", "1180, 1240, 1230"), TXT("target", "Target & date", "1400 by March")],
 [T("analyse", "Analyse a practice test", "Misses → causes → the one fix", "🧪", [LONG("misses", "Missed questions", "Q4 algebra — picked C, answer B, misread 'not'; Q9 inference — ran out of time…"), TXT("score", "Score on this test", "1260")],
    "Analyse the misses from a practice test scoring {score}: {misses}. Table (Question | Topic | Cause: content gap, misread, careless, timing or guess | Fixable in a week?), a kv of counts by cause with the share of lost points each represents, bullets on the top 3 patterns, and a callout on the single highest-value fix.", "table, kv, bullets, callout", "Analyse", "Tagging causes…"),
  T("heatmap", "Weakness heat-map", "Topics ranked by miss rate and trend", "🔥", [LONG("log", "Miss log so far", "paste your accumulated misses or topic tallies…")],
    "Build a weakness heat-map from: {log}. Table (Topic | Attempts | Misses | Miss rate | Trend | Priority) sorted by priority, bullets on topics that are too noisy to judge (too few attempts), steps for a 7-day study order derived from the table, and a callout on topics to stop studying because they are already reliable.", "table, bullets, steps, callout", "Map it", "Colouring cells…"),
  T("redrill", "Targeted re-drill", "Questions engineered against your usual cause", "🎯", [TXT("topic", "Topic to re-drill", "comma splices", True), CH("cause", "Usual cause", ["Content gap", "Misread the question", "Careless", "Timing", "Guessing"], "Content gap"), CH("n", "Questions", ["5", "10"], "5")],
    "Write {n} questions on {topic} in the profile test's format, engineered against the cause '{cause}' (for misreads include negations and 'except'; for timing add a seconds budget; for content gaps ramp the difficulty): cards (question with options, meta = seconds budget), a table (No. | Answer | What to notice), and a quote with a pre-question ritual for this cause.", "cards, table, quote", "Re-drill", "Loading questions…"),
  T("project", "Project my score", "Where the trend lands on test day", "📈", [TXT("recent", "Latest practice scores & dates", "1230 on 3 Feb, 1260 on 17 Feb"), CH("hours", "Hours per week", ["3", "6", "10", "15+"], "6")],
    "Project the profile's score from the history and {recent} at {hours} hours a week: kv (current estimate, projected score on the target date, likelihood band of hitting the target, points still needed), a table (Weeks from now | Expected score | Milestone check), bullets on the assumptions behind the projection, and a callout on when to move the test date instead.", "kv, table, bullets, callout", "Project", "Extrapolating…"),
  T("weekly", "Weekly review", "Five questions, one table, next week's plan", "📋", [],
    "Write this week's review for the profile: a checklist of 5 questions to answer from the week's practice (tests taken, misses logged, fixes applied, timing, sleep), a table (Metric | Last week | This week | Direction) with blanks to fill, steps for next week's plan built from the profile's target and history, and a quote with a one-line focus for the week.", "checklist, table, steps, quote", "Review week", "Tallying…")])
